  const money=n=>n===null?'A consultar':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
  const el=id=>document.getElementById(id);
  function nowLocal(now=new Date()) {const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return {date:parts.year+'-'+parts.month+'-'+parts.day,minutes:Number(parts.hour)*60+Number(parts.minute),year:Number(parts.year),month:Number(parts.month)-1};}
  const dateObject=d=>new Date(d+'T12:00:00Z');
  const formatDate=d=>new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(dateObject(d));
  function validDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(dateObject(d).valueOf())&&dateObject(d).toISOString().slice(0,10)===d;}
  function hoursFor(d){const day=dateObject(d).getUTCDay();return day===0?[9,12]:day===6?[8,18]:[8,20];}
  function timesFor(d,now=new Date()){if(!validDate(d))return [];const current=nowLocal(now);if(d<current.date)return [];const [start,end]=hoursFor(d);const options=[];for(let minutes=start*60;minutes<end*60;minutes+=30){if(d===current.date&&minutes<=current.minutes)continue;options.push(String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0'));}return options;}
  const initial=nowLocal();let month=initial.month,year=initial.year;let selectedDate='',selectedTime='',requestMessage='',reviewTrigger=null;
  for(const s of services){const option=document.createElement('option');option.value=s.id;option.textContent=s.name+' · '+money(s.price);el('service').append(option);}
