  function updateSummary(){const s=selectedService();el('summary-service').textContent=s?.name||'Ainda não escolhido';el('summary-price').textContent=s?money(s.price):'—';el('summary-date').textContent=selectedDate?formatDate(selectedDate):'Escolha no calendário';el('summary-time').textContent=selectedTime||'Escolha um horário';el('date').value=selectedDate;el('time').value=selectedTime;el('service-note').textContent=s?.price===null?'O valor deste serviço será informado pelo studio.':'Os valores exibidos seguem o catálogo fornecido e serão confirmados no atendimento.';}
  function renderCalendar(){const first=new Date(Date.UTC(year,month,1));const total=new Date(Date.UTC(year,month+1,0)).getUTCDate();el('month-label').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',month:'long',year:'numeric'}).format(first);el('previous-month').disabled=year===initial.year&&month===initial.month;const box=el('calendar-days');box.replaceChildren();for(let blank=0;blank<first.getUTCDay();blank++){const spacer=document.createElement('span');spacer.setAttribute('aria-hidden','true');box.append(spacer);}const today=nowLocal().date;for(let day=1;day<=total;day++){const date=year+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const button=document.createElement('button');button.type='button';button.className='calendar-day'+(date===today?' today':'')+(date===selectedDate?' selected':'');button.textContent=day;button.dataset.date=date;button.disabled=date<today||timesFor(date).length===0;button.setAttribute('aria-label',formatDate(date)+(date===today?', hoje':''));button.setAttribute('aria-pressed',String(date===selectedDate));button.addEventListener('click',()=>chooseDate(date));box.append(button);}}
  function renderTimes(){const box=el('time-options');box.replaceChildren();if(!selectedDate){el('hours-note').textContent='Escolha um dia para ver os horários que pode solicitar.';return;}const [start,end]=hoursFor(selectedDate);el('hours-note').textContent='Atendimento neste dia: '+start+'h às '+end+'h. Horários sujeitos à confirmação.';const options=timesFor(selectedDate);if(selectedTime&&!options.includes(selectedTime))selectedTime='';if(!options.length){const p=document.createElement('p');p.className='no-hours';p.textContent='Os horários de hoje já passaram. Escolha outro dia para solicitar seu atendimento.';box.append(p);return;}for(const time of options){const button=document.createElement('button');button.type='button';button.className='time-button'+(time===selectedTime?' selected':'');button.textContent=time;button.dataset.time=time;button.setAttribute('aria-pressed',String(time===selectedTime));button.setAttribute('aria-label','Solicitar horário '+time);button.addEventListener('click',()=>{selectedTime=time;box.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});clearError();updateSummary();el('selection-status').textContent='Horário desejado: '+time+'.';});box.append(button);}}
  function chooseDate(date){if(!validDate(date)||date<nowLocal().date||!timesFor(date).length)throw new Error('Escolha uma data com horários futuros.');selectedDate=date;selectedTime='';clearError();renderCalendar();renderTimes();updateSummary();el('calendar-days').querySelector('[data-date="'+date+'"]')?.focus({preventScroll:true});el('selection-status').textContent='Dia desejado: '+formatDate(date)+'. Escolha agora o horário.';}
  el('previous-month').addEventListener('click',()=>{if(year===initial.year&&month===initial.month)return;month--;if(month<0){month=11;year--;}renderCalendar();});el('next-month').addEventListener('click',()=>{month++;if(month>11){month=0;year++;}renderCalendar();});el('service').addEventListener('change',()=>{clearError();updateSummary();});
  function renderServices(category='Todos') {
    const box=el('service-cards');
    box.replaceChildren();
    for(const service of services.filter(s=>category==='Todos'||s.category===category)) {
      const photo=servicePhotos[service.id];
      const card=document.createElement('article');
      card.className='service-card';
      const figure=document.createElement('figure');
      figure.className='service-photo';
      const image=document.createElement('img');
      image.src=photo.src;image.alt=photo.alt;image.width=photo.width;image.height=photo.height;
      image.loading='lazy';image.decoding='async';image.style.objectPosition=photo.position;
      const caption=document.createElement('figcaption');caption.textContent=photo.caption;
      figure.append(image,caption);
      const content=document.createElement('div');content.className='service-card-content';
      const categoryLabel=document.createElement('span');categoryLabel.className='service-category';categoryLabel.textContent=service.category;
      const title=document.createElement('h3');title.textContent=service.name;
      const description=document.createElement('p');description.textContent=service.description;
      const bottom=document.createElement('div');bottom.className='service-card-bottom';
      const price=document.createElement('strong');price.className='service-price';price.textContent=money(service.price);
      const button=document.createElement('button');button.type='button';button.textContent='Escolher';button.dataset.service=service.id;
      button.setAttribute('aria-label','Escolher '+service.name);
      button.addEventListener('click',()=>{el('service').value=service.id;updateSummary();clearError();el('agenda').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});el('service').focus({preventScroll:true});});
      bottom.append(price,button);content.append(categoryLabel,title,description,bottom);card.append(figure,content);box.append(card);
    }
  }
  document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderServices(b.dataset.category);}));
  function fail(message,focus){el('form-error').textContent=message;el('form-error').hidden=false;focus?.focus();return false;}
  function getRequest(){const s=selectedService();if(!s)throw new Error('Escolha o serviço que deseja solicitar.');if(!validDate(selectedDate)||selectedDate<nowLocal().date)throw new Error('Escolha um dia futuro no calendário.');if(!selectedTime||!timesFor(selectedDate).includes(selectedTime))throw new Error('Escolha um horário válido para o dia selecionado.');const name=el('customer-name').value.trim();if(name.length<2||name.length>80)throw new Error('Digite seu nome para continuar.');const notes=el('notes').value.trim();return {service:s,name,date:selectedDate,time:selectedTime,notes};}
  function buildMessage(r){return ['Olá, Studio Estefani Bruschi! Gostaria de solicitar um horário.','','Nome: '+r.name,'Serviço: '+r.service.name,'Valor de referência: '+money(r.service.price),'Dia desejado: '+formatDate(r.date),'Horário desejado: '+r.time+' (horário de Brasília)',...(r.notes?['Observação: '+r.notes]:[]),'','Vocês têm disponibilidade nesse dia e horário? Aguardo a confirmação.'].join('\n');}
  function openReview(trigger){let request;try{request=getRequest();}catch(error){let focus;if(!selectedService()){focus=el('service');}else if(!validDate(selectedDate)||selectedDate<nowLocal().date){selectedDate='';selectedTime='';const current=nowLocal();year=current.year;month=current.month;renderCalendar();renderTimes();updateSummary();focus=el('calendar-days').querySelector('button:not(:disabled)')||el('next-month');}else if(!selectedTime||!timesFor(selectedDate).includes(selectedTime)){selectedTime='';renderCalendar();renderTimes();updateSummary();focus=el('time-options').querySelector('button')||el('calendar-days').querySelector('button:not(:disabled)')||el('next-month');}else{focus=el('customer-name');}fail(error.message,focus);return false;}clearError();requestMessage=buildMessage(request);const detail=el('review-details');detail.replaceChildren();for(const [label,value]of [['Nome',request.name],['Serviço',request.service.name],['Valor de referência',money(request.service.price)],['Dia desejado',formatDate(request.date)],['Horário desejado',request.time],...(request.notes?[['Observação',request.notes]]:[])]){const div=document.createElement('div');const small=document.createElement('span');small.textContent=label;const strong=document.createElement('strong');strong.textContent=value;div.append(small,strong);detail.append(div);}el('whatsapp-link').href='https://wa.me/'+phone+'?text='+encodeURIComponent(requestMessage);el('copy-status').textContent='';reviewTrigger=trigger||document.activeElement;el('review-dialog').showModal();document.body.style.overflow='hidden';return true;}
  el('booking-form').addEventListener('submit',e=>{e.preventDefault();openReview(e.submitter);});el('customer-name').addEventListener('input',clearError);
  const dialog=el('review-dialog');document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';reviewTrigger?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});el('copy-request').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(requestMessage);el('copy-status').textContent='Mensagem copiada. Você também pode colar no WhatsApp.';}catch{el('copy-status').textContent='A cópia automática não está disponível. Use o botão para continuar no WhatsApp.';}});
  const menu=document.querySelector('.menu-toggle'),nav=el('navigation');const closeMenu=()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open');};menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});
  renderServices();renderCalendar();renderTimes();updateSummary();
  const context=document.modelContext;if(context?.registerTool){const controller=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}};register({name:'list_studio_services',title:'Conhecer serviços do studio',description:'Lista serviços e valores de referência exibidos no site.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>services.map(({id,name,price,category})=>({id,name,price,category}))});register({name:'stage_studio_request',title:'Preparar solicitação de horário',description:'Seleciona serviço, dia e horário no formulário. Não abre o WhatsApp, não envia mensagem e não reserva horário.',inputSchema:{type:'object',properties:{serviceId:{type:'string'},date:{type:'string'},time:{type:'string'}},required:['serviceId','date','time'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!services.some(s=>s.id===input.serviceId))return {ok:false,error:'Escolha um serviço da lista do studio.'};if(!validDate(input.date)||!timesFor(input.date).length)return {ok:false,error:'Escolha uma data com horários futuros.'};if(!timesFor(input.date).includes(input.time))return {ok:false,error:'Escolha um horário de meia em meia hora dentro do atendimento deste dia.',availableTimes:timesFor(input.date)};el('service').value=input.serviceId;const d=dateObject(input.date);year=d.getUTCFullYear();month=d.getUTCMonth();selectedDate=input.date;selectedTime=input.time;renderCalendar();renderTimes();updateSummary();clearError();return {service:selectedService().name,date:selectedDate,time:selectedTime,status:'solicitação preparada, sem envio'};}});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
